import React, { useEffect, useState } from "react";
import { fetchUser } from "../../../services/Api";
import FriendRequest from './FriendRequest';



function  FriendRequests({activeUser}) {
    const [requestsList, setRequestsList] = useState([]);
    const [requestsUsers, setRequestsUsers] = useState([]);
    const [loading, setLoading] = useState(true);

    useEffect(() => {
        const getRequests = async () => {
          const response = await fetchUser(activeUser.token, activeUser.email);
          const user = await response.json();
          setRequestsList(user.friendRequests);
        };
    
        getRequests();
      }, [activeUser]);
    
      useEffect(() => {
        const getRequestsUsers = async () => {
          const usersPromises = requestsList.map(async (request) => {
            const response = await fetchUser(activeUser.token, request);
            return response.json();
          });
    
          const users = await Promise.all(usersPromises);
          console.log(users);
          setRequestsUsers(users);
          setLoading(false);
        };
    
        getRequestsUsers();
      }, [requestsList, activeUser]);





    return (
        <div className="FriendRequests">
            {loading ? (
        <p>Loading...</p>
      ) :
            requestsUsers.length === 0 ? (
                <p>No friend requests</p>
            ) : (
                requestsUsers.map((user) =>
                    <FriendRequest
                        activeUser={activeUser}
                        // userPic={user.picture}
                        // displayName={user.displayName}
                        // email={user.email} 
                        user={user}
                        requestsUsers={requestsUsers}
                        setRequestsUsers={setRequestsUsers}
                         />
                ))
            }

        </div>
    );    

}
export default FriendRequests;
